	assertEntry(t, graph, "b", []string{"a"}, nil)

	impacts := mustImpacts(t, graph, "a")
	assertImpactOnce(t, impacts, "b", 1, []string{"a", "b"})

	out := mustExport(t, graph, "b")
	if want := `{"nodes":["a","b"],"edges":[{"from":"a","to":"b"}]}`; out != want {
